// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testRegression_property() public {
        address ownerBefore = c.Owner();
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Command.selector, address(0x5678), ""));
        if (!success) {
            address ownerAfter = c.Owner();
            assertTrue(ownerAfter == ownerBefore);
        } else {
            assertTrue(false);
        }
    }
}
